-- Actual database rollback only. No provider request can execute before transaction rollback.
CREATE TEMP TABLE window_test_receipt(result jsonb);
DO $test$
DECLARE rid bigint; res jsonb; before_a jsonb; before_p jsonb; before_aug jsonb; before_holds jsonb; h text; did_reject boolean;
BEGIN
 PERFORM pg_advisory_xact_lock(2026083000261022);
 SELECT to_jsonb(x) INTO before_a FROM population_top3000_202608_202609_v1.acquisition_control x WHERE singleton FOR UPDATE;
 SELECT to_jsonb(x) INTO before_p FROM population_top3000_202608_202609_v1.pipeline_control x WHERE singleton FOR UPDATE;
 SELECT to_jsonb(x) INTO before_aug FROM population_top3000_202608_202609_v1.pipeline_task x WHERE task_id='d377d980-5dbd-4276-a2c9-d5638c60b668';
 SELECT jsonb_agg(to_jsonb(x) ORDER BY task_id) INTO before_holds FROM population_top3000_202608_202609_v1.pipeline_task x WHERE family_id='CTX02' AND stage='VALIDATE';
 h:=encode(sha256(convert_to(pg_get_functiondef('population_top3000_202608_202609_v1.ctx02_fullwindow_continue_v6(text,bigint,bigint,bigint,bigint)'::regprocedure),'UTF8')),'hex');
 INSERT INTO population_top3000_202608_202609_v1.pipeline_event(event,details) VALUES('CTX02_FULLWINDOW_CONTINUATION_REVIEW_V6',jsonb_build_object('owner_id',before_a->>'owner_id','owner_fence',3,'stop_generation',1,'scope_sha256',before_a->>'scope_sha256','assignment_event_id',20231,'claim_event_id',21885,'approved',true,'reviewer','ROLLBACK_FIXTURE_REVIEW_ONLY','producer','september_executor','code_commit',repeat('a',40),'function_sha256',h)) RETURNING event_id INTO rid;
 did_reject:=false; BEGIN PERFORM population_top3000_202608_202609_v1.ctx02_fullwindow_continue_v6('changed-owner',3,1,20231,rid); EXCEPTION WHEN OTHERS THEN IF SQLERRM='CTX02_WINDOW_CONTROLLER_ADMISSION_REQUIRED' THEN did_reject:=true;ELSE RAISE; END IF;END; IF NOT did_reject THEN RAISE EXCEPTION 'OWNER_TEST_FAILED';END IF;
 did_reject:=false; BEGIN UPDATE population_top3000_202608_202609_v1.acquisition_control SET stopped=true; PERFORM population_top3000_202608_202609_v1.ctx02_fullwindow_continue_v6('top3000-completion-20261024-root-5db48b32d103',3,1,20231,rid); EXCEPTION WHEN OTHERS THEN IF SQLERRM='CTX02_WINDOW_CONTROLLER_ADMISSION_REQUIRED' THEN did_reject:=true;ELSE RAISE;END IF;END; IF NOT did_reject THEN RAISE EXCEPTION 'STOP_TEST_FAILED';END IF;
 did_reject:=false; BEGIN UPDATE population_top3000_202608_202609_v1.pipeline_task SET checkpoint='{}' WHERE task_id='da79b746-8550-41c9-a6f0-3d87f4e352fd'; PERFORM population_top3000_202608_202609_v1.ctx02_fullwindow_continue_v6('top3000-completion-20261024-root-5db48b32d103',3,1,20231,rid); EXCEPTION WHEN OTHERS THEN IF SQLERRM='WINDOW_EXACT_TASK_PREIMAGE_CHANGED' THEN did_reject:=true;ELSE RAISE;END IF;END; IF NOT did_reject THEN RAISE EXCEPTION 'CURSOR_TEST_FAILED';END IF;
 did_reject:=false; BEGIN UPDATE population_top3000_202608_202609_v1.acquisition_control SET max_source_bytes=stored_bytes; PERFORM population_top3000_202608_202609_v1.ctx02_fullwindow_continue_v6('top3000-completion-20261024-root-5db48b32d103',3,1,20231,rid); EXCEPTION WHEN OTHERS THEN IF SQLERRM='WINDOW_MEASURED_RESOURCES_EXHAUSTED' THEN did_reject:=true;ELSE RAISE;END IF;END; IF NOT did_reject THEN RAISE EXCEPTION 'RESOURCE_TEST_FAILED';END IF;
 did_reject:=false; BEGIN UPDATE population_top3000_202608_202609_v1.acquisition_control SET admitted_until=clock_timestamp()-interval '1 second';PERFORM population_top3000_202608_202609_v1.ctx02_fullwindow_continue_v6('top3000-completion-20261024-root-5db48b32d103',3,1,20231,rid); EXCEPTION WHEN OTHERS THEN IF SQLERRM='CTX02_WINDOW_CONTROLLER_ADMISSION_REQUIRED' THEN did_reject:=true;ELSE RAISE;END IF;END; IF NOT did_reject THEN RAISE EXCEPTION 'ADMISSION_EXPIRY_TEST_FAILED';END IF;
 did_reject:=false; BEGIN UPDATE population_top3000_202608_202609_v1.pipeline_event SET details=jsonb_set(details,'{expires_at}',to_jsonb(clock_timestamp()-interval '1second')) WHERE event_id=21885;PERFORM population_top3000_202608_202609_v1.ctx02_fullwindow_continue_v6('top3000-completion-20261024-root-5db48b32d103',3,1,20231,rid); EXCEPTION WHEN OTHERS THEN IF SQLERRM='CTX02_WINDOW_LIVE_CLAIM_PINS_CHANGED' THEN did_reject:=true;ELSE RAISE;END IF;END; IF NOT did_reject THEN RAISE EXCEPTION 'CLAIM_EXPIRY_TEST_FAILED';END IF;
 did_reject:=false; BEGIN UPDATE population_top3000_202608_202609_v1.continuation_clear_queue_v6 SET owner_id='stale' WHERE clearing_id='514c87e6ff2cd981bd73e5dd6d129b118e58e8db99a1d996f8cabf878576728d';PERFORM population_top3000_202608_202609_v1.ctx02_fullwindow_continue_v6('top3000-completion-20261024-root-5db48b32d103',3,1,20231,rid); EXCEPTION WHEN OTHERS THEN IF SQLERRM='WINDOW_CLEARING_PREIMAGE_CHANGED' THEN did_reject:=true;ELSE RAISE;END IF;END; IF NOT did_reject THEN RAISE EXCEPTION 'QUEUE_OWNER_TEST_FAILED';END IF;
 did_reject:=false; BEGIN UPDATE population_top3000_202608_202609_v1.pipeline_task SET input_versions=jsonb_set(input_versions,'{scope_sha256}',to_jsonb('stale'::text)) WHERE task_id='da79b746-8550-41c9-a6f0-3d87f4e352fd';PERFORM population_top3000_202608_202609_v1.ctx02_fullwindow_continue_v6('top3000-completion-20261024-root-5db48b32d103',3,1,20231,rid); EXCEPTION WHEN OTHERS THEN IF SQLERRM='WINDOW_EXACT_TASK_PREIMAGE_CHANGED' THEN did_reject:=true;ELSE RAISE;END IF;END; IF NOT did_reject THEN RAISE EXCEPTION 'TASK_VERSION_TEST_FAILED';END IF;
 did_reject:=false; BEGIN UPDATE population_top3000_202608_202609_v1.ctx02_census_page_v1 SET source_sha256=repeat('a',64) WHERE partition_key='ctx02-census-v1:082572b99c04ab298a3794bc6013aca7114cd07f8c1d78564e6ad6b4209a3ef9';PERFORM population_top3000_202608_202609_v1.ctx02_fullwindow_continue_v6('top3000-completion-20261024-root-5db48b32d103',3,1,20231,rid); EXCEPTION WHEN OTHERS THEN IF SQLERRM='WINDOW_SOURCE_CHAIN_CHANGED' THEN did_reject:=true;ELSE RAISE;END IF;END; IF NOT did_reject THEN RAISE EXCEPTION 'SOURCE_HASH_TEST_FAILED';END IF;
 did_reject:=false; BEGIN UPDATE population_top3000_202608_202609_v1.pipeline_provider_lease SET released_at=NULL WHERE ctid=(SELECT ctid FROM population_top3000_202608_202609_v1.pipeline_provider_lease WHERE released_at IS NOT NULL LIMIT 1);PERFORM population_top3000_202608_202609_v1.ctx02_fullwindow_continue_v6('top3000-completion-20261024-root-5db48b32d103',3,1,20231,rid); EXCEPTION WHEN OTHERS THEN IF SQLERRM='CTX02_WINDOW_PROVIDER_EFFECT_UNRESOLVED' THEN did_reject:=true;ELSE RAISE;END IF;END; IF NOT did_reject THEN RAISE EXCEPTION 'UNKNOWN_PROVIDER_TEST_FAILED';END IF;
 res:=population_top3000_202608_202609_v1.ctx02_fullwindow_continue_v6('top3000-completion-20261024-root-5db48b32d103',3,1,20231,rid);
 IF (SELECT count(*) FROM population_top3000_202608_202609_v1.continuation_clear_queue_v6 WHERE clearing_id IN('514c87e6ff2cd981bd73e5dd6d129b118e58e8db99a1d996f8cabf878576728d','c2fe46b3436686aec58f7ff285482fd2cfa997128f96d4c86292228f5335d356') AND status='WAITING_OUTPUT' AND claimed_at IS NOT NULL AND attempts=0)<>2 THEN RAISE EXCEPTION 'WAITING_OUTPUT_TIME_TEST_FAILED';END IF;
 IF res->>'status' IS DISTINCT FROM 'INTEGRATED_WAITING_FOR_DATA_COMMIT' THEN RAISE EXCEPTION 'POSITIVE_TEST_FAILED';END IF;
 IF population_top3000_202608_202609_v1.ctx02_fullwindow_continue_v6('top3000-completion-20261024-root-5db48b32d103',3,1,20231,rid)->>'replay' IS DISTINCT FROM 'true' THEN RAISE EXCEPTION 'REPLAY_TEST_FAILED';END IF;
 IF before_aug IS DISTINCT FROM (SELECT to_jsonb(x) FROM population_top3000_202608_202609_v1.pipeline_task x WHERE task_id='d377d980-5dbd-4276-a2c9-d5638c60b668') OR before_holds IS DISTINCT FROM (SELECT jsonb_agg(to_jsonb(x) ORDER BY task_id) FROM population_top3000_202608_202609_v1.pipeline_task x WHERE family_id='CTX02' AND stage='VALIDATE') THEN RAISE EXCEPTION 'UNRELATED_CHANGE_TEST_FAILED';END IF;
 INSERT INTO window_test_receipt VALUES(jsonb_build_object('status','PASS','function_sha256',h,'proof',res,'tests',jsonb_build_array('owner_rejection','stop_rejection','cursor_rejection','resource_rejection','exact_positive_requeue','replay','august_and_validate_unchanged','admission_expiry','claim_expiry','queue_owner','task_version','source_hash','unknown_provider'),'actual_provider_calls',0,'all_mutations_rolled_back',true));
END;$test$;
SELECT * FROM window_test_receipt;
